const fs = require('fs');

let apiKey = 'xyz';
if (fs.existsSync('/etc/typesense-api-key')) {
  apiKey = fs.readFileSync('/etc/typesense-api-key', 'utf8').trim();
}

console.log('Using API key:', apiKey);

async function run() {
  try {
    // Check health
    const healthRes = await fetch('http://127.0.0.1:8108/health', {
      headers: { 'X-TYPESENSE-API-KEY': apiKey }
    });
    const health = await healthRes.json();
    console.log('Health:', health);

    // Delete existing collections if any
    const collectionsRes = await fetch('http://127.0.0.1:8108/collections', {
      headers: { 'X-TYPESENSE-API-KEY': apiKey }
    });
    const collections = await collectionsRes.json();
    console.log('Existing collections:', collections.map(c => c.name));

    for (const c of collections) {
      console.log('Deleting collection:', c.name);
      await fetch(`http://127.0.0.1:8108/collections/${c.name}`, {
        method: 'DELETE',
        headers: { 'X-TYPESENSE-API-KEY': apiKey }
      });
    }

    // Delete existing rules if any
    const rulesRes = await fetch('http://127.0.0.1:8108/analytics/rules', {
      headers: { 'X-TYPESENSE-API-KEY': apiKey }
    });
    if (rulesRes.ok) {
      const rulesObj = await rulesRes.json();
      const rules = rulesObj.rules || [];
      console.log('Existing rules:', rules.map(r => r.name));
      for (const r of rules) {
        console.log('Deleting rule:', r.name);
        await fetch(`http://127.0.0.1:8108/analytics/rules/${r.name}`, {
          method: 'DELETE',
          headers: { 'X-TYPESENSE-API-KEY': apiKey }
        });
      }
    }

    // Create catalog collection
    console.log('Creating catalog collection...');
    const catalogSchema = {
      name: 'catalog',
      fields: [
        { name: 'id', type: 'string' },
        { name: 'name', type: 'string' },
        { name: 'category', type: 'string' },
        { name: 'price', type: 'float' }
      ]
    };
    const createCatalogRes = await fetch('http://127.0.0.1:8108/collections', {
      method: 'POST',
      headers: {
        'X-TYPESENSE-API-KEY': apiKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(catalogSchema)
    });
    console.log('Create catalog status:', createCatalogRes.status, await createCatalogRes.json());

    // Create popular_queries collection
    console.log('Creating popular_queries collection...');
    const popularQueriesSchema = {
      name: 'popular_queries',
      fields: [
        { name: 'q', type: 'string' },
        { name: 'count', type: 'int32' }
      ]
    };
    const createPopularRes = await fetch('http://127.0.0.1:8108/collections', {
      method: 'POST',
      headers: {
        'X-TYPESENSE-API-KEY': apiKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(popularQueriesSchema)
    });
    console.log('Create popular status:', createPopularRes.status, await createPopularRes.json());

    // Create no_hits_queries collection
    console.log('Creating no_hits_queries collection...');
    const noHitsQueriesSchema = {
      name: 'no_hits_queries',
      fields: [
        { name: 'q', type: 'string' },
        { name: 'count', type: 'int32' }
      ]
    };
    const createNoHitsRes = await fetch('http://127.0.0.1:8108/collections', {
      method: 'POST',
      headers: {
        'X-TYPESENSE-API-KEY': apiKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(noHitsQueriesSchema)
    });
    console.log('Create no_hits status:', createNoHitsRes.status, await createNoHitsRes.json());

    // Create popular_queries rule
    console.log('Creating popular_queries analytics rule...');
    const popularRule = {
      name: 'catalog_popular_queries_rule',
      type: 'popular_queries',
      params: {
        source: {
          collections: ['catalog']
        },
        destination: {
          collection: 'popular_queries'
        },
        limit: 1000
      }
    };
    const createPopularRuleRes = await fetch('http://127.0.0.1:8108/analytics/rules', {
      method: 'POST',
      headers: {
        'X-TYPESENSE-API-KEY': apiKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(popularRule)
    });
    console.log('Create popular rule status:', createPopularRuleRes.status, await createPopularRuleRes.json());

    // Create nohits_queries rule
    console.log('Creating nohits_queries analytics rule...');
    const noHitsRule = {
      name: 'catalog_no_hits_queries_rule',
      type: 'nohits_queries',
      params: {
        source: {
          collections: ['catalog']
        },
        destination: {
          collection: 'no_hits_queries'
        },
        limit: 1000
      }
    };
    const createNoHitsRuleRes = await fetch('http://127.0.0.1:8108/analytics/rules', {
      method: 'POST',
      headers: {
        'X-TYPESENSE-API-KEY': apiKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(noHitsRule)
    });
    console.log('Create no_hits rule status:', createNoHitsRuleRes.status, await createNoHitsRuleRes.json());

  } catch (err) {
    console.error('Error:', err);
  }
}

run();

